-- ============================================================
-- SEED EXT 4: Módulo 14 — Passive Voice (ex 232-300)
-- Novos tópicos: passivo em diferentes registros, pseudo-passivo
-- (be + adj), passivo em reported speech, passivo avançado TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'passive-voice';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo passive-voice não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: passivo em registered speech / reporting
  (cid,41,232,'gap_fill','It _____ (report/passive) that the CEO had approved the controversial merger.','was reported',NULL,'"It was reported that + clause" = impersonal passive for reported speech.','medium'),
  (cid,41,233,'multiple_choice','Which impersonal passive construction is MOST formal in academic writing?','It has been suggested that further research is needed.','["They suggest that further research is needed.","People have suggested that further research is needed.","It has been suggested that further research is needed.","Somebody has suggested that further research is needed."]','"It has been suggested that..." = impersonal passive, highly formal academic.','medium'),
  (cid,41,234,'gap_fill','It _____ (widely/believe/passive) that the drug was effective until a 2018 meta-analysis cast doubt.','was widely believed',NULL,'"It was widely believed that..." = impersonal passive + adverb.','medium'),
  (cid,41,235,'multiple_choice','Which pair shows both correct impersonal passive forms?','It is known that X causes Y. / X is known to cause Y.','["It is known that X causes Y (correct). / X is known causing Y (wrong).","It is known that X causes Y. / X is known to cause Y.","It is knew that X causes Y. / X is known to cause Y.","It is known that X causes Y. / X is known cause Y."]','"It is known that + clause" = "X is known to + infinitive" — two correct forms of impersonal passive.','hard'),
  (cid,41,236,'gap_fill','Scientists _____ (consider/passive) to have underestimated the long-term effects of microplastic contamination.','are considered',NULL,'"Are considered to have + past participle" = passive + perfect infinitive.','hard'),

  -- BLOCK 42: pseudo-passivo (be + adjective derived from PP)
  (cid,42,237,'multiple_choice','What is the difference between "The window was broken by the storm" and "The window was broken when we arrived"?','The first is a passive (action by agent). The second is a stative passive (resultant state).','["They are identical","The first is a passive (action by agent). The second is a stative passive (resultant state).","Both describe actions","Both describe states"]','Be + past participle can be action (passive) OR state (stative). Context determines which.','hard'),
  (cid,42,238,'gap_fill','After the meeting, all parties _____ (satisfy/stative passive) with the outcome of the negotiations.','were satisfied',NULL,'"Were satisfied" = stative passive (resultant state of satisfaction).','medium'),
  (cid,42,239,'multiple_choice','Which sentence uses a STATIVE passive (describing a state, not an action)?','The laboratory was well-equipped for high-throughput genetic sequencing.','["The data were analyzed by three independent reviewers (action passive).","The laboratory was well-equipped for high-throughput genetic sequencing.","The results were published in Nature (action passive).","The sample was contaminated by an unknown substance (action passive)."]','"Was well-equipped" = stative: describes the state of the lab, not who equipped it.','hard'),
  (cid,42,240,'gap_fill','The corridor _____ (connect/stative passive) to the main building through an enclosed walkway.','is connected',NULL,'"Is connected to" = stative passive (spatial/structural relationship).','easy'),
  (cid,42,241,'multiple_choice','Which adjective-passive pairs are STATIVE (not action)?','The results were unexpected. The data were skewed. The room was heated.','["The samples were analyzed (action). The results were expected (stative). The room was demolished (action).","The results were unexpected. The data were skewed. The room was heated.","The results were published (action stative). The data were collected (action). The room was converted (action).","All are action passives."]','"Unexpected / skewed / heated" = adjectives functioning as stative passives (derived from past participles).','hard'),

  -- BLOCK 43: passivo em relativas e cláusulas reduzidas
  (cid,43,242,'gap_fill','The report _____ (submit/passive) last month _____ (need/passive) revision before publication.','submitted / needs',NULL,'Reduced passive relative: "the report submitted last month" = "the report that was submitted."','hard'),
  (cid,43,243,'multiple_choice','Which sentence correctly uses a reduced passive relative clause?','Samples collected from three different sites were analyzed independently.','["Samples that they collected from three sites were analyzed independently.","Samples being collected from three different sites were analyzed independently (PC = ongoing, wrong here).","Samples collected from three different sites were analyzed independently.","Samples to be collected from three sites were analyzed independently (future infinitive)."]','"Samples collected" = reduced passive relative = "samples that were collected."','medium'),
  (cid,43,244,'gap_fill','The applications _____ (receive/passive) after the deadline _____ (not/consider/passive) for funding.','received / will not be considered',NULL,'Reduced passive relative (received = that were received) + modal passive.','hard'),
  (cid,43,245,'multiple_choice','What does "Data gathered over a ten-year period suggest..." use?','A reduced passive relative clause: "gathered" = "that was gathered."','["A present continuous","An active gerund","A reduced passive relative clause: ''gathered'' = ''that was gathered.''","A past perfect"]','"Gathered" = past participle functioning as reduced passive relative modifier.','medium'),

  -- BLOCK 44: causativo passivo (have/get + object + past participle)
  (cid,44,246,'gap_fill','She _____ (have) the manuscript _____ (proofread) by a professional editor before submission.','had / proofread',NULL,'"Have + object + past participle" = causative passive (arrange for someone to do).','hard'),
  (cid,44,247,'multiple_choice','What is the causative construction "get + object + past participle" used for?','Arranging for someone else to do something for you.','["Describing an unintended accident","Arranging for someone else to do something for you.","Expressing a completed action in the past","Describing ongoing actions"]','"Get/have + object + PP" = causative passive — you arrange for someone to do it to the object.','medium'),
  (cid,44,248,'gap_fill','The professor _____ (get) the data _____ (verify) by an external statistician.','got / verified',NULL,'"Got + object + past participle" = informal causative passive.','medium'),
  (cid,44,249,'multiple_choice','Which sentence is a correct CAUSATIVE passive?','The department had its budget reviewed by an independent auditor.','["The department had reviewed its budget by an independent auditor.","The department had its budget being reviewed by an independent auditor.","The department had its budget reviewed by an independent auditor.","The department got the budget reviewing by an independent auditor."]','"Had + object + past participle" = causative (the department arranged for the review).','hard'),
  (cid,44,250,'gap_fill','You should _____ (have) your methodology _____ (check) by your supervisor before the experiment begins.','have / checked',NULL,'"Have + object + past participle" = advice about using causative construction.','medium'),

  -- BLOCK 45: TOEFL Reading — passivo em textos científicos
  (cid,45,251,'multiple_choice','[TOEFL Reading] "Participants were randomly assigned to control or experimental conditions using a computerized randomization protocol." The passive is used here to:','Focus on the process rather than emphasize the researchers as agents.','["Show uncertainty about who assigned participants","Focus on the process rather than emphasize the researchers as agents.","Indicate that participants chose their conditions","Avoid repetition in the paragraph"]','Methods section passive: agent is de-emphasized to foreground the procedure.','easy'),
  (cid,45,252,'gap_fill','[TOEFL Reading] "It _____ (argue/passive) that the current regulation is insufficient to address the scope of the problem." Formal academic form?','has been argued / is argued',NULL,'"It has been argued / It is argued that..." = impersonal passive for academic argument attribution.','medium'),
  (cid,45,253,'multiple_choice','[TOEFL Reading] "The mechanism by which the enzyme catalyzes the reaction is not yet fully understood." "Is not yet fully understood" is:','A present passive (negative, hedged) describing incomplete scientific knowledge.','["An active present continuous","A present passive (negative, hedged) describing incomplete scientific knowledge.","A past passive","A future passive"]','Present passive negative: "is not understood" = ongoing state of not being understood.','easy'),
  (cid,45,254,'gap_fill','[TOEFL Reading] "The findings _____ (interpret/passive/must) in the context of the study''s methodological constraints." Best form?','must be interpreted',NULL,'"Must be interpreted" = modal passive for mandatory contextual qualification.','easy'),

  -- BLOCK 46: TOEFL Speaking — passivo integrado
  (cid,46,255,'production','[TOEFL Speaking — 45s] A lecture discusses scientific peer review. Describe the process using passive voice throughout (at least 5 passive forms).','',NULL,'When a research paper is submitted to an academic journal, it is first assessed by the editor, who determines whether the topic is appropriate for the journal. If accepted for review, the manuscript is then sent anonymously to two or three independent experts in the field. Reviewers are asked to evaluate the methodology, the clarity of the findings, and the overall contribution to the literature. After their assessments are received, a decision is made by the editor: the paper may be accepted, rejected, or — most commonly — returned to the authors with revisions requested. Once revisions have been made and approved, the paper is published and made available to the scientific community.','hard'),
  (cid,46,256,'production','[TOEFL Speaking — 45s] A reading argues that endangered languages should be preserved. Use passive voice, stative passive, impersonal passive (it is argued that), and causative passive (have/get something done).','',NULL,'It has been argued that linguistic diversity is as vital to human culture as biodiversity is to the natural world. When a language dies, unique ways of categorizing experience, encoding ecological knowledge, and organizing social relationships are lost forever. Many minority languages are currently endangered, with fewer and fewer speakers remaining alive. Governments and international organizations have been urged to have comprehensive documentation carried out before these languages disappear entirely. Oral traditions can be recorded, grammars can be compiled, and digital archives can be established — but only if this work is prioritized and properly funded. It is also argued that communities themselves should be empowered to lead revitalization efforts.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,257,'production','[TOEFL Writing — 150 words] Write an academic paragraph on climate change policy using: passive voice (×4 at least), impersonal passive "it is argued/suggested/known that" (×2), causative passive (×1), stative passive (×1), modal passive (×2).','',NULL,'Climate change policy represents one of the most contested arenas of contemporary international governance. It is widely acknowledged that greenhouse gas emissions must be reduced substantially by 2050 if the worst projections of the IPCC are to be avoided. It has been argued by some economists that a carbon tax is the most efficient mechanism for driving emissions reductions, as it allows markets to be realigned toward lower-carbon choices. Others contend that binding international agreements are needed, with enforcement mechanisms that have long been considered legally and politically unfeasible. It is known that voluntary commitments have consistently fallen short of targets. Richer nations are expected to have their emissions independently verified by international monitors — an arrangement that has been resisted by several major emitters. Without binding accountability, decarbonization targets will remain aspirational rather than operational.','hard'),
  (cid,47,258,'production','[TOEFL Writing — 200 words] Write an integrated essay paragraph about artificial intelligence regulation. Use impersonal passive, modal passives, stative passive, causative passive, and reduced passive relative clauses.','',NULL,'Artificial intelligence systems deployed in high-stakes domains — healthcare, criminal justice, and financial services — present regulatory challenges that are not yet fully understood by policymakers. It is generally accepted that algorithms trained on biased datasets can perpetuate and amplify existing societal inequities, yet effective remedies have been difficult to implement. It has been argued that developers should be required to have their models independently audited before deployment, with findings made available to regulators and, in some cases, the public. Systems found to exhibit discriminatory patterns should be withdrawn from service until the underlying problems are corrected. However, it is also known that excessive regulation risks stifling the innovation that may ultimately yield social benefits. A proportionate approach — where the level of scrutiny applied to any given AI system is calibrated to the potential harm it could cause — has been proposed by several international bodies as the most defensible framework.','hard'),
  (cid,47,259,'production','[TOEFL Writing — Error Correction] Fix passive errors: "It is argue that education reforms are needed. The results should interpreted with caution. The sample was collecting over six months. She had the report to be written by her assistant. The data are known cause significant variation."','',NULL,'It is argue → It is argued (past participle required in impersonal passive); should interpreted → should be interpreted (modal passive needs ''be'' before past participle); was collecting → was collected (passive = was + past participle, not continuous); had the report to be written → had the report written (causative passive: have + object + past participle, no ''to be''); are known cause → are known to cause (passive + infinitive: ''are known to cause'').','hard'),
  (cid,47,260,'production','[TOEFL Writing — 200 words] Write a conclusion paragraph for a TOEFL essay on "The impact of technology on human connection." Use: passive voice, impersonal passive, stative passive, modal passive, causative get-passive, and present perfect passive.','',NULL,'In conclusion, the impact of digital technology on human connection is complex and cannot be evaluated in simple terms. It has been established through decades of social research that face-to-face interaction remains fundamental to psychological well-being and social cohesion. Yet it has also been demonstrated that technology can facilitate meaningful relationships across distances that would previously have been insurmountable. The concern most frequently expressed is that social media platforms are designed — get-passively structured — to maximize engagement at the cost of depth, meaning that users are subtly manipulated rather than genuinely connected. It has been argued that the design of technology platforms should be regulated so that user well-being is prioritized over commercial metrics. What is certain is that the relationship between technology and human connection will continue to be shaped by the choices made by developers, regulators, and users alike, and that these choices must be made with greater deliberation and public accountability than has been demonstrated thus far.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
